scripts.de_helper_script:
#!/bin/bash
# Rexon DE helper — привилегированная установка/восстановление DE.
# Запускается ИСКЛЮЧИТЕЛЬНО через pkexec (polkit action org.rexon.de-install,
# auth_admin_keep: подтверждённый пароль держится несколько минут для окна
# Rexon). Принимает только строго валидируемые de_id + family (+ опц.
# log_path под /tmp). Имена пакетов берёт из ВСТРОЕННОЙ таблицы. НЕ выполняет произвольный код.
set -euo pipefail

# Стабильная C-локаль: вывод pacman/apt/… всегда по-английски, чтобы
# Python-парсер прогресса (_RE_SKIP «is up to date -- skipping» и т.п.)
# ловил пропуски/прогресс на ЛЮБОЙ системной локали (иначе на русской
# pacman пишет «не устарел -- пропускается» и «✓ уже установлено» не
# срабатывает).
export LC_ALL=C LANG=C

# ⚠️ Никакого ввода с клавиатуры. Пакетный менеджер задаёт вопросы сам себе
# (члены группы, выбор поставщика) и при --noconfirm отвечает на них по
# умолчанию, не читая stdin. Но если завтра в какой-то ветке --noconfirm
# потеряется, а stdin окажется живым (терминал, из которого запустили Rexon,
# или незакрытая труба), вопрос ЗАВИСНЕТ — молча, до самого таймаута в
# полчаса. Отрезаем stdin один раз здесь: тогда худшее, что может случиться,
# — быстрый отказ вместо вечного ожидания.
exec </dev/null

# ── Язык сообщений ─────────────────────────────────────────────────
# Отметка ниже говорит Rexon, что помощник понимает --lang.
# REXON_HELPER_LANG_ARG=1
# Первый аргумент --lang=<код> необязателен; код сверяется с белым
# списком из po/LINGUAS, всё прочее — английский. Тексты — ТОЛЬКО из
# таблицы ниже (вшиты при генерации); вставки %1..%9 подставляются как
# данные, а не как формат printf и не как команды.
rx_lang=en
case "${1:-}" in
    --lang=*)
        case "${1#--lang=}" in
            ru) rx_lang=ru ;;
        esac
        shift ;;
esac
rx_text() {
    case "$rx_lang:$1" in
        ru:bad_de_id) rx_t='плохой de_id: %1' ;;
        *:bad_de_id) rx_t='bad de_id: %1' ;;
        ru:bad_family_arg) rx_t='плохой family: %1' ;;
        *:bad_family_arg) rx_t='bad family: %1' ;;
        ru:db_update_failed) rx_t='обновление БД не удалось' ;;
        *:db_update_failed) rx_t='package database update failed' ;;
        ru:de_args) rx_t='ожидается 2-3 аргумента: de_id family [log_path]' ;;
        *:de_args) rx_t='expected 2-3 arguments: de_id family [log_path]' ;;
        ru:dm_already) rx_t='экран входа уже настроен (%1) — не меняю' ;;
        *:dm_already) rx_t='a login screen is already set up (%1) — leaving it as is' ;;
        ru:dm_enable_failed) rx_t='не удалось включить %1: %2' ;;
        *:dm_enable_failed) rx_t='could not enable %1: %2' ;;
        ru:dm_enable_failed_plain) rx_t='не удалось включить %1: systemctl вернул ошибку' ;;
        *:dm_enable_failed_plain) rx_t='could not enable %1: systemctl returned an error' ;;
        ru:dm_enabled) rx_t='display-manager включён: %1' ;;
        *:dm_enabled) rx_t='display manager enabled: %1' ;;
        ru:dm_none) rx_t='экран входа не включён (нет установленного DM из списка стола)' ;;
        *:dm_none) rx_t='login screen not enabled (no installed display manager from this desktop'\''s list)' ;;
        ru:empty_pkg_list) rx_t='пустой список пакетов для %1' ;;
        *:empty_pkg_list) rx_t='empty package list for %1' ;;
        ru:log_outside_tmp) rx_t='log_path вне /tmp|/var/tmp: %1' ;;
        *:log_outside_tmp) rx_t='log_path is outside /tmp|/var/tmp: %1' ;;
        ru:no_setpriv) rx_t='нет setpriv (util-linux) — журнал хода не ведётся' ;;
        *:no_setpriv) rx_t='setpriv (util-linux) is missing — the progress log is not kept' ;;
        ru:no_user_group) rx_t='нет группы у пользователя %1' ;;
        *:no_user_group) rx_t='user %1 has no group' ;;
        ru:not_via_pkexec) rx_t='запуск не через pkexec' ;;
        *:not_via_pkexec) rx_t='not started through pkexec' ;;
        ru:unknown_de_pair) rx_t='неизвестная пара DE/семейство: %1' ;;
        *:unknown_de_pair) rx_t='unknown desktop environment/family pair: %1' ;;
        ru:unsupported_family) rx_t='неподдерживаемое семейство: %1' ;;
        *:unsupported_family) rx_t='unsupported family: %1' ;;
        *) rx_t="$1" ;;
    esac
}
rx_say() {
    local rx_t rx_out="" rx_n
    rx_text "$1"; shift
    while [ -n "$rx_t" ]; do
        case "$rx_t" in
            %[1-9]*) rx_n="${rx_t:1:1}"; rx_out+="${!rx_n-}"; rx_t="${rx_t:2}" ;;
            *) rx_out+="${rx_t:0:1}"; rx_t="${rx_t:1}" ;;
        esac
    done
    printf '%s: %s\n' rexon-de-helper "$rx_out"
}
die() { rx_say "$@" >&2; exit 2; }

[ "$#" -ge 2 ] && [ "$#" -le 3 ] \
    || die de_args
de_id="$1"
family="$2"
log_path="${3:-}"

# de_id / family — строгий формат (allowlist символов). Реальная проверка
# валидности пары — через таблицу ниже (неизвестная пара → die).
printf '%s' "$de_id"  | grep -Eq '^[A-Za-z0-9._-]+$' || die bad_de_id "$de_id"
printf '%s' "$family" | grep -Eq '^[a-z]+$'          || die bad_family_arg "$family"

# log_path (если задан): журнал хода установки для окна Rexon. Файл создаёт
# Rexon заранее (mkstemp), и принадлежит он ВЫЗВАВШЕМУ. Поэтому и пишет его
# процесс С ПРАВАМИ ВЫЗВАВШЕГО (setpriv), а не root: какой бы файл ни
# оказался по этому пути к моменту записи, root туда не пишет и владельца
# не меняет.
#
# ⛔ Дыра, которую это закрыло (28.09.2026). Прежде: realpath, затем
# `chown root` + запись root'ом + в конце `chown $PKEXEC_UID` — по строке
# пути, через минуты установки. Каталог в пути принадлежит пользователю, и
# подменить его ссылкой (/tmp/a/b → /etc) можно было в любой момент до
# конца установки: в конце root отдавал пользователю, скажем, /etc/shadow.
# Действие org.rexon.de-install при этом стояло в правиле «без пароля» —
# молчаливый root для любого процесса сеанса.
#
# exit-маркер __REXON_EXIT__ фильтруется tail-парсером Rexon.
if [ -n "$log_path" ]; then
    case "$log_path" in
        /tmp/?*|/var/tmp/?*) : ;;
        *) die log_outside_tmp "$log_path" ;;
    esac
    log_uid="${PKEXEC_UID:-}"
    printf '%s' "$log_uid" | grep -Eq '^[0-9]+$' || die not_via_pkexec
    log_gid="$(getent passwd "$log_uid" 2>/dev/null | cut -d: -f4)"
    printf '%s' "$log_gid" | grep -Eq '^[0-9]+$' || die no_user_group "$log_uid"
    if command -v setpriv >/dev/null 2>&1; then
        exec > >(exec setpriv --reuid="$log_uid" --regid="$log_gid" --clear-groups \
                     -- tee -a -- "$log_path" >/dev/null) 2>&1
        log_pid=$!
        trap 'ec=$?; echo "__REXON_EXIT__$ec"; exec >&- 2>&-; wait "$log_pid" 2>/dev/null || true; exit "$ec"' EXIT
    else
        # Без setpriv журнал не ведём вовсе: писать чужой файл от root нельзя.
        rx_say no_setpriv >&2
    fi
fi

# Пакеты для пары de_id|family — ТОЛЬКО из встроенной таблицы (allowlist).
pkgs="$(
  case "$de_id|$family" in
        "cinnamon-mint|arch") echo cinnamon cinnamon-translations nemo nemo-fileroller gnome-terminal lightdm lightdm-slick-greeter ;;
