        "niri|arch") echo niri swaybg swayidle swaylock waybar fuzzel alacritty mako thunar grim slurp wl-clipboard polkit-gnome xdg-desktop-portal-gnome xwayland-satellite otf-font-awesome ttf-nerd-fonts-symbols ;;
        "niri|fedora") echo niri swaybg swayidle swaylock waybar fuzzel alacritty mako thunar grim slurp wl-clipboard xdg-desktop-portal-gnome fontawesome-fonts ;;
        "niri|suse") echo niri swaybg swayidle swaylock waybar fuzzel alacritty mako grim slurp wl-clipboard xdg-desktop-portal-gnome fontawesome-fonts symbols-only-nerd-fonts ;;
        "niri|alpine") echo niri swaybg swayidle swaylock waybar fuzzel alacritty mako grim slurp wl-clipboard xdg-desktop-portal-gnome font-awesome font-nerd-fonts-symbols ;;
        "sway|arch") echo sway swaybg swayidle swaylock waybar wofi wmenu foot mako thunar grim slurp wl-clipboard polkit-gnome xdg-desktop-portal-wlr xdg-desktop-portal-gtk xorg-xwayland otf-font-awesome ttf-nerd-fonts-symbols ;;
        "sway|debian") echo sway swaybg swayidle swaylock waybar wofi foot mako-notifier grim slurp wl-clipboard xdg-desktop-portal-wlr fonts-font-awesome ;;
        "sway|fedora") echo sway swaybg swayidle swaylock waybar wofi foot mako grim slurp wl-clipboard xdg-desktop-portal-wlr fontawesome-fonts ;;
        "sway|suse") echo sway swaybg swayidle swaylock waybar wofi foot mako grim slurp wl-clipboard xdg-desktop-portal-wlr fontawesome-fonts symbols-only-nerd-fonts ;;
        "sway|void") echo sway swaybg swayidle swaylock waybar wofi foot mako grim slurp wl-clipboard font-awesome nerd-fonts-symbols-ttf ;;
        "sway|alpine") echo sway swaybg swayidle swaylock waybar wofi foot mako grim slurp wl-clipboard font-awesome font-nerd-fonts-symbols ;;
