        "river|fedora") echo river-classic waybar fuzzel foot mako swaybg grim slurp wl-clipboard xdg-desktop-portal-wlr fontawesome-fonts ;;
        "river|void") echo river waybar fuzzel foot mako swaybg grim slurp wl-clipboard xdg-desktop-portal-wlr font-awesome nerd-fonts-symbols-ttf ;;
        "river|alpine") echo river-classic waybar fuzzel foot mako swaybg grim slurp wl-clipboard xdg-desktop-portal-wlr font-awesome font-nerd-fonts-symbols ;;
        "wayfire|arch") echo wayfire wf-shell wcm foot mako thunar grim slurp wl-clipboard polkit-gnome xdg-desktop-portal-wlr xdg-desktop-portal-gtk xorg-xwayland ;;
        "wayfire|debian") echo wayfire wf-shell wcm foot mako-notifier grim slurp wl-clipboard xdg-desktop-portal-wlr ;;
        "wayfire|fedora") echo wayfire wf-shell wayfire-config-manager foot mako grim slurp wl-clipboard xdg-desktop-portal-wlr ;;
        "wayfire|suse") echo wayfire wf-shell wcm foot mako grim slurp wl-clipboard xdg-desktop-portal-wlr ;;
        "wayfire|void") echo wayfire wf-shell wcm foot mako grim slurp wl-clipboard xdg-desktop-portal-wlr ;;
    *) die unknown_de_pair "$de_id|$family" ;;
  esac
)"
[ -n "$pkgs" ] || die empty_pkg_list "$de_id|$family"

# Команды менеджера пакетов по семейству (--needed = restore/repair:
# установленное пропускается).
case "$family" in
    arch) PKG_CMD=(pacman -S --needed --noconfirm --noprogressbar --color never) ;;
    arch) UPD_CMD=(pacman -Sy --noconfirm --noprogressbar --color never) ;;
    debian) PKG_CMD=(apt-get install -y --no-install-recommends) ;;
    debian) UPD_CMD=(apt-get update -q) ;;
    fedora) PKG_CMD=(dnf install -y) ;;
    fedora) UPD_CMD=(dnf makecache -q) ;;
    suse) PKG_CMD=(zypper install -y --no-recommends) ;;
    suse) UPD_CMD=(zypper refresh -q) ;;
    alpine) PKG_CMD=(apk add --no-progress) ;;
    alpine) UPD_CMD=(apk update) ;;
    void) PKG_CMD=(xbps-install -y) ;;
    void) UPD_CMD=(xbps-install -S) ;;
    solus) PKG_CMD=(eopkg it -y) ;;
    solus) UPD_CMD=(eopkg ur) ;;
    clear) PKG_CMD=(swupd bundle-add) ;;
    clear) UPD_CMD=(swupd update --download) ;;
    alt) PKG_CMD=(apt-get install -y) ;;
    alt) UPD_CMD=(apt-get update -q) ;;
    *) die unsupported_family "$family" ;;
esac

# ⛔ Никакого `eval`: команды — МАССИВЫ аргументов, список пакетов
# разбивается на слова РОВНО один раз и оболочке на разбор не отдаётся.
# Прежнее `eval "${PKG_CMD/'{PKGS}'/$pkgs}"` держало дверь открытой: стоило
# в таблицу попасть имени с метасимволом, и это была команда, а не пакет.

# 1) Обновление БД (иначе --needed может упасть на устаревшей БД).
"${UPD_CMD[@]}" || die db_update_failed

# 2) Установка пакетов DE (имена — только из встроенной таблицы выше).
read -r -a pkg_list <<<"$pkgs"
[ "${#pkg_list[@]}" -gt 0 ] || die empty_pkg_list "$de_id|$family"
"${PKG_CMD[@]}" "${pkg_list[@]}"

# 3) Экран входа в ТОМ ЖЕ сеансе авторизации (без 2-го пароля). Только при
# systemd. Имя DM берётся ТОЛЬКО из встроенного списка И обязано
# присутствовать в $pkgs данного DE.
#
# ⚠️ Чужой экран входа НЕ трогаем. Подмена экрана входа — заметное для
# человека вмешательство в общесистемную сущность, и делать её молча,
# «заодно» с установкой стола, нельзя: у человека может стоять plasmalogin,
# gdm, greetd. Включаем DM этого стола ТОЛЬКО когда включённого экрана входа
# в системе нет вовсе (иначе после перезагрузки не будет входа в графику).
#
# ⚠️ И в любом исходе говорим правду: сделал — что сделал, не смог — почему.
# Раньше ошибка systemctl уходила в /dev/null, а «включён» печаталось
# безусловно — вывод сообщал об успехе там, где ничего не произошло.
if command -v systemctl >/dev/null 2>&1; then
    # Что стоит сейчас: цель симлинка display-manager.service, а если
    # симлинка нет — первый включённый юнит из известного списка.
    cur_dm=""
    if [ -L "/etc/systemd/system/display-manager.service" ]; then
        cur_target="$(readlink -f "/etc/systemd/system/display-manager.service" 2>/dev/null || true)"
        cur_dm="${cur_target##*/}"
        cur_dm="${cur_dm%.service}"
        [ -n "$cur_dm" ] || cur_dm="display-manager"
    else
        for known in display-manager plasmalogin sddm gdm gdm3 lightdm lxdm greetd ly cosmic-greeter slim nodm xdm entrance emptty tbsm; do
            state="$(systemctl is-enabled "$known.service" 2>/dev/null || true)"
            case "$state" in
                enabled|enabled-runtime|alias|indirect|static) cur_dm="$known"; break ;;
            esac
        done
    fi

    if [ -n "$cur_dm" ]; then
        rx_say dm_already "$cur_dm"
    else
        # Маппинг ИМЯ-ЮНИТА → ИМЯ-ПАКЕТА (имена обычно совпадают; исключение —
        # Plasma Login Manager: юнит plasmalogin, пакет plasma-login-manager).
        pkg_for_dm() {
            case "$1" in
                plasmalogin) printf '%s' 'plasma-login-manager' ;;
                *) printf '%s' "$1" ;;
            esac
        }
        dm_done=""
        for dm in plasmalogin cosmic-greeter lightdm gdm sddm; do
            case "$dm" in
                "plasmalogin" | "cosmic-greeter" | "lightdm" | "gdm" | "sddm") : ;;
                *) continue ;;
            esac
            dm_pkg="$(pkg_for_dm "$dm")"
            # dm-ПАКЕТ должен быть в пакет-листе ЭТОГО DE (точное слово).
            printf ' %s ' "$pkgs" | grep -q " $dm_pkg " || continue
            # И юнит реально установлен (unit-файл существует).
            systemctl cat "$dm.service" >/dev/null 2>&1 || continue
            # --force для DM, не Provides display-manager.service (PLM).
            force=""
            case "$dm" in
                "plasmalogin") force="--force" ;;
            esac
            # shellcheck disable=SC2086
            if err="$(systemctl enable $force "$dm.service" 2>&1)"; then
                rx_say dm_enabled "$dm"
            else
                if [ -n "$err" ]; then
                    rx_say dm_enable_failed "$dm" "$err"
                else
                    rx_say dm_enable_failed_plain "$dm"
                fi
            fi
            dm_done="$dm"
            break
        done
        [ -n "$dm_done" ] || rx_say dm_none
    fi
fi
exit 0

scripts.pkg_helper_script:
#!/bin/bash
# Rexon pkg helper — привилегированные операции пакетного менеджера.
#
# Запускается ИСКЛЮЧИТЕЛЬНО через pkexec (polkit action org.rexon.pkg).
# Принимает операцию и ИМЕНА пакетов. Команды — из ВСТРОЕННЫХ таблиц,
# семейство пакетного менеджера помощник определяет САМ по ЭТОЙ машине.
# Ни оболочки, ни `eval`, ни путей: произвольный код не выполняется.
# Единственный файл, который помощник принимает, — пакет, собранный
# пересборкой Rexon от пользователя (операция install-built, только из
# каталога пересборок вызвавшего; см. её раздел ниже).
#
# ⛔ ДЫРА, КОТОРУЮ ЭТО ЗАКРЫЛО (25.09.2026)
# Прежний помощник (1) брал семейство из АРГУМЕНТА, (2) разрешал в именах
# пакетов символ '/' (allowlist '^[A-Za-z0-9@._+:/-]+$') и (3) собирал
# команду через eval. Любой процесс сеанса мог позвать
#     pkexec rexon-pkg-helper debian install /tmp/evil.deb
# и apt-get (а равно dnf, zypper) поставил бы ЛОКАЛЬНЫЙ ФАЙЛ, сценарии
# установки которого идут ОТ ROOT. Семейство при этом не обязано было
# совпадать с машиной — хватало любого установленного менеджера.
# Вторая половина дыры — 'remove': имя не проверялось ничем, кроме
# символов, и 'remove linux' сносил ядро.
set -euo pipefail
export LC_ALL=C LANG=C
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
# Ни ввода с клавиатуры (вопрос менеджера завис бы молча до таймаута), ни
# чужого рабочего каталога: pkexec его НЕ меняет, а 'dnf install evil.rpm'
# ищет файл именно в нём.
exec </dev/null
cd /

# ── Язык сообщений ─────────────────────────────────────────────────
# Отметка ниже говорит Rexon, что помощник понимает --lang.
# REXON_HELPER_LANG_ARG=1
# Первый аргумент --lang=<код> необязателен; код сверяется с белым
# списком из po/LINGUAS, всё прочее — английский. Тексты — ТОЛЬКО из
# таблицы ниже (вшиты при генерации); вставки %1..%9 подставляются как
# данные, а не как формат printf и не как команды.
rx_lang=en
case "${1:-}" in
    --lang=*)
        case "${1#--lang=}" in
            ru) rx_lang=ru ;;
        esac
        shift ;;
esac
rx_text() {
    case "$rx_lang:$1" in
        ru:arg_dash) rx_t='аргумент начинается с '\''-'\'' (флаг-инъекция?): %1' ;;
        *:arg_dash) rx_t='argument starts with '\''-'\'' (flag injection?): %1' ;;
        ru:bad_dm) rx_t='недопустимый display-manager: %1' ;;
        *:bad_dm) rx_t='invalid display manager: %1' ;;
        ru:bad_greeter) rx_t='недопустимое приветствие: %1' ;;
        *:bad_greeter) rx_t='invalid greeter: %1' ;;
        ru:bad_op) rx_t='недопустимая операция: %1' ;;
        *:bad_op) rx_t='invalid operation: %1' ;;
        ru:build_only_kept) rx_t='пакеты, нужные только для сборки, оставлены' ;;
        *:build_only_kept) rx_t='build-only packages kept' ;;
        ru:build_only_not_ours) rx_t='%1 ставили не для этой сборки — оставлен' ;;
        *:build_only_not_ours) rx_t='%1 was not installed for this build — kept' ;;
        ru:built_args) rx_t='install-built ожидает: plain|replace file [pkg...]' ;;
        *:built_args) rx_t='install-built expects: plain|replace file [pkg...]' ;;
        ru:built_bad_name) rx_t='это не файл пакета, собранный makepkg: %1' ;;
        *:built_bad_name) rx_t='not a package file made by makepkg: %1' ;;
        ru:built_copy_failed) rx_t='не скопировать файл пакета: %1' ;;
        *:built_copy_failed) rx_t='cannot copy the package file: %1' ;;
        ru:built_no_home) rx_t='не найден домашний каталог пользователя %1' ;;
        *:built_no_home) rx_t='cannot find the home folder of user %1' ;;
        ru:built_not_callers) rx_t='файл пакета принадлежит не вызвавшему: %1' ;;
        *:built_not_callers) rx_t='the package file does not belong to the caller: %1' ;;
        ru:built_not_file) rx_t='файл пакета — ссылка или не обычный файл: %1' ;;
        *:built_not_file) rx_t='the package file is a link or not a regular file: %1' ;;
        ru:built_outside) rx_t='файл пакета вне каталога пересборок Rexon вызвавшего: %1' ;;
        *:built_outside) rx_t='the package file is outside the caller'\''s Rexon rebuild folder: %1' ;;
        ru:built_unreachable) rx_t='файл пакета недоступен: %1' ;;
        *:built_unreachable) rx_t='the package file is not accessible: %1' ;;
        ru:current_de_pkg) rx_t='отказ снять пакет рабочего стола или экрана входа, которые сейчас используются: %1' ;;
        *:current_de_pkg) rx_t='refusing to remove a package of the desktop or login screen in use: %1' ;;
        ru:dm_already_default) rx_t='%1 уже основной экран входа — менять нечего' ;;
        *:dm_already_default) rx_t='%1 is already the login screen — nothing to change' ;;
        ru:dm_backend_unsupported) rx_t='на этой системе Rexon пока не умеет переключать экран входа' ;;
        *:dm_backend_unsupported) rx_t='on this system Rexon can'\''t switch the login screen yet' ;;
        ru:dm_masked) rx_t='экран входа %1 выключен в системе (замаскирован)' ;;
        *:dm_masked) rx_t='the login screen %1 is switched off in the system (masked)' ;;
        ru:dm_no_greeter_prog) rx_t='приветствие %1 не установлено' ;;
        *:dm_no_greeter_prog) rx_t='the greeter %1 is not installed' ;;
        ru:dm_no_pam) rx_t='нет файла настроек входа (PAM) %1' ;;
        *:dm_no_pam) rx_t='the sign-in settings file (PAM) %1 is missing' ;;
        ru:dm_no_program) rx_t='нет программы экрана входа %1' ;;
        *:dm_no_program) rx_t='the login screen program %1 is missing' ;;
        ru:dm_no_unit) rx_t='служба экрана входа %1 не установлена' ;;
        *:dm_no_unit) rx_t='the service of the login screen %1 is not installed' ;;
        ru:dm_no_xorg) rx_t='этому экрану входа нужен Xorg, а он не установлен' ;;
        *:dm_no_xorg) rx_t='this login screen needs Xorg, and Xorg is not installed' ;;
        ru:dm_switch_failed) rx_t='не удалось сделать %1 экраном входа: %2 — прежний оставлен' ;;
        *:dm_switch_failed) rx_t='could not make %1 the login screen: %2 — the previous one is kept' ;;
        ru:dm_switch_mismatch) rx_t='после переключения система не считает %1 экраном входа — прежний возвращён' ;;
        *:dm_switch_mismatch) rx_t='after switching, the system doesn'\''t show %1 as the login screen — the previous one is restored' ;;
        ru:dm_switched) rx_t='теперь экран входа — %1 (был %2); он появится после перезагрузки' ;;
        *:dm_switched) rx_t='%1 is now the login screen (it was %2); it appears after a restart' ;;
        ru:dm_switched_first) rx_t='теперь экран входа — %1; он появится после перезагрузки' ;;
        *:dm_switched_first) rx_t='%1 is now the login screen; it appears after a restart' ;;
        ru:dm_text_login) rx_t='greetd настроен на текстовый вход — рабочий стол не запустится' ;;
        *:dm_text_login) rx_t='greetd is set up for text sign-in — the desktop won'\''t start' ;;
        ru:enable_dm_one) rx_t='enable-dm ожидает ровно один DM' ;;
        *:enable_dm_one) rx_t='enable-dm expects exactly one DM' ;;
        ru:family_mismatch) rx_t='семейство из аргумента (%1) не совпало с определённым по машине (%2) — работаю по определённому' ;;
        *:family_mismatch) rx_t='family from the argument (%1) does not match the one detected on this machine (%2) — using the detected one' ;;
        ru:family_unknown) rx_t='семейство пакетного менеджера этой машины не определено' ;;
        *:family_unknown) rx_t='could not determine the package manager family of this machine' ;;
        ru:greeter_not_lightdm) rx_t='приветствие выбирается только для LightDM' ;;
        *:greeter_not_lightdm) rx_t='a greeter can only be chosen for LightDM' ;;
        ru:lightdm_no_greeter) rx_t='у LightDM не установлено ни одного приветствия' ;;
        *:lightdm_no_greeter) rx_t='LightDM has no greeter installed' ;;
        ru:no_cmd) rx_t='команда для %1 не задана' ;;
        *:no_cmd) rx_t='no command is set for %1' ;;
        ru:no_pm) rx_t='нет менеджера пакетов: %1' ;;
        *:no_pm) rx_t='package manager not found: %1' ;;
        ru:no_systemctl) rx_t='нет systemctl' ;;
        *:no_systemctl) rx_t='systemctl not found' ;;
        ru:no_systemd) rx_t='в этой системе не работает systemd — экран входа выбирает её собственная система инициализации' ;;
        *:no_systemd) rx_t='this system isn'\''t running systemd — the login screen is chosen by its own init' ;;
        ru:no_work_dir) rx_t='не создать рабочий каталог' ;;
        *:no_work_dir) rx_t='cannot create a working directory' ;;
        ru:not_a_name) rx_t='имя пакета, а не путь: %1' ;;
        *:not_a_name) rx_t='a package name is expected, not a path: %1' ;;
        ru:not_in_tables) rx_t='отказ ставить пакет, которого нет в таблицах Rexon: %1' ;;
        *:not_in_tables) rx_t='refusing to install a package that is not in Rexon'\''s tables: %1' ;;
        ru:not_via_pkexec) rx_t='запуск не через pkexec' ;;
        *:not_via_pkexec) rx_t='not started through pkexec' ;;
        ru:op_needs_pkg) rx_t='%1 требует хотя бы один пакет' ;;
        *:op_needs_pkg) rx_t='%1 needs at least one package' ;;
        ru:pkg_args) rx_t='ожидается >=2 аргумента: family op [pkg...]' ;;
        *:pkg_args) rx_t='expected at least 2 arguments: family op [pkg...]' ;;
        ru:prev_dm_auto) rx_t='Если %1 не запустится, Rexon сам вернёт %2 при этой же загрузке.' ;;
        *:prev_dm_auto) rx_t='If %1 fails to start, Rexon brings back %2 by itself on that boot.' ;;
        ru:prev_dm_back) rx_t='Чтобы вернуть %1 из текстовой консоли (Ctrl+Alt+F3), войдите и выполните:' ;;
        *:prev_dm_back) rx_t='To bring back %1 from a text console (Ctrl+Alt+F3), sign in and run:' ;;
        ru:prev_dm_header) rx_t='Rexon сменил экран входа: был %1, стал %2.' ;;
        *:prev_dm_header) rx_t='Rexon changed the login screen from %1 to %2.' ;;
        ru:rebuild_arch_only) rx_t='%1 работает только с pacman (Arch)' ;;
        *:rebuild_arch_only) rx_t='%1 works only with pacman (Arch)' ;;
        ru:switch_dm_args) rx_t='switch-dm ждёт экран входа и, для LightDM, приветствие: unit [greeter]' ;;
        *:switch_dm_args) rx_t='switch-dm expects a login screen and, for LightDM, a greeter: unit [greeter]' ;;
        ru:unsupported_family) rx_t='неподдерживаемое семейство: %1' ;;
        *:unsupported_family) rx_t='unsupported family: %1' ;;
        ru:update_no_pkgs) rx_t='update не принимает пакеты' ;;
        *:update_no_pkgs) rx_t='update takes no packages' ;;
        ru:vital_pkg) rx_t='жизненно важный пакет не удаляю: %1' ;;
        *:vital_pkg) rx_t='refusing to remove a vital package: %1' ;;
        *) rx_t="$1" ;;
    esac
}
rx_say() {
    local rx_t rx_out="" rx_n
    rx_text "$1"; shift
    while [ -n "$rx_t" ]; do
        case "$rx_t" in
            %[1-9]*) rx_n="${rx_t:1:1}"; rx_out+="${!rx_n-}"; rx_t="${rx_t:2}" ;;
            *) rx_out+="${rx_t:0:1}"; rx_t="${rx_t:1}" ;;
        esac
    done
    printf '%s: %s\n' rexon-pkg-helper "$rx_out"
}
die() { rx_say "$@" >&2; exit 2; }
have() { command -v "$1" >/dev/null 2>&1; }

# ── Семейство пакетного менеджера: ТОЛЬКО по этой машине ─────────────
# Порядок тот же, что у ядра (DistroDetector.family): ID из os-release →
# ID_LIKE → наличие бинарников. os-release не исполняется и в оболочку не
# подаётся — значение вынимает sed.
osr_field() {
    local f v
    for f in /etc/os-release /usr/lib/os-release; do
        [ -r "$f" ] || continue
        v="$(sed -n "s/^$1=//p" "$f" | head -n1)"
        v="${v%\"}"; v="${v#\"}"; v="${v%\'}"; v="${v#\'}"
        printf '%s' "$v" | tr 'A-Z' 'a-z'
        return 0
    done
}

family_of_id() {
    case "$1" in
        arch|cachyos|manjaro|endeavouros|garuda|artix|steamos|archcraft|blendos|archbang|crystal) printf '%s' arch; return 0 ;;
        debian|ubuntu|linuxmint|pop|elementary|zorin|kali|parrot|mx|mxlinux|lmde|raspbian|peppermint|tuxedo|astra|osnova|boss) printf '%s' debian; return 0 ;;
        fedora|rhel|centos|almalinux|rocky|ol|nobara|ultramarine|bazzite|redos|rosa) printf '%s' fedora; return 0 ;;
        opensuse|opensuse-leap|opensuse-tumbleweed|sle|sles) printf '%s' suse; return 0 ;;
        gentoo|calculate) printf '%s' gentoo; return 0 ;;
        alpine) printf '%s' alpine; return 0 ;;
        void) printf '%s' void; return 0 ;;
        nixos) printf '%s' nix; return 0 ;;
        solus) printf '%s' solus; return 0 ;;
        clear-linux-os) printf '%s' clear; return 0 ;;
        alt|altlinux|simply) printf '%s' alt; return 0 ;;
        *) return 1 ;;
    esac
}

detect_family() {
    local id like
    id="$(osr_field ID)"
    if [ -n "$id" ] && family_of_id "$id"; then return 0; fi
    for like in $(osr_field ID_LIKE); do
        if family_of_id "$like"; then return 0; fi
    done
    # APT-RPM (ALT): apt-get есть, dpkg нет.
    if have apt-get; then
        if have dpkg; then printf '%s' debian; return 0; fi
        if have rpm; then printf '%s' alt; return 0; fi
        printf '%s' debian; return 0
    fi
    if have pacman; then printf '%s' arch; return 0; fi
    if have dnf; then printf '%s' fedora; return 0; fi
    if have yum; then printf '%s' fedora; return 0; fi
    if have zypper; then printf '%s' suse; return 0; fi
    if have emerge; then printf '%s' gentoo; return 0; fi
    if have apk; then printf '%s' alpine; return 0; fi
    if have xbps-install; then printf '%s' void; return 0; fi
    if have eopkg; then printf '%s' solus; return 0; fi
    if have swupd; then printf '%s' clear; return 0; fi
    return 1
}

# ── Аргументы ────────────────────────────────────────────────────────
# argv прежний (family op [pkg...]) — по нему зовёт движок, — но ПЕРВЫЙ
# аргумент больше ничего не решает: команду выбирает только определённое
# выше семейство. Расхождение не отказ, а запись в журнал: подсунуть через
# него чужой менеджер пакетов уже нельзя.
[ "$#" -ge 2 ] || die pkg_args
claimed="$1"; op="$2"; shift 2

family="$(detect_family || true)"
[ -n "$family" ] || die family_unknown
case "$family" in
    arch|debian|fedora|suse|gentoo|alpine|void|solus|clear|alt) : ;;
    *) die unsupported_family "$family" ;;
esac
if [ "$claimed" != "$family" ]; then
    rx_say family_mismatch "$claimed" "$family" >&2
fi

case "$op" in
    install|remove|update|enable-dm|switch-dm|build-deps|install-built) : ;;
    *) die bad_op "$op" ;;
esac

# ── Пересборка по рецепту Arch: две узкие операции ───────────────────
# Пересборка Rexon (repo_rebuild) собирает пакет ОТ ПОЛЬЗОВАТЕЛЯ и
# зовёт помощник дважды, под тем же действием polkit, что и установка
# остального, — пароль спрашивают один раз:
#   build-deps dep...                         недостающее для сборки,
#       pacman -S --needed --asdeps; строка — имя и, возможно,
#       ограничение версии ('cmake>=3.20'), как её отдаёт 'pacman -T';
#   install-built plain|replace file [pkg...] собранный файл, pacman -U
#       (replace — '--ask=4': заменить конфликтующий установленный), затем
#       'pacman -Rns' сборочных pkg; не снялись — не ошибка.
# ⛔ Снять install-built может ТОЛЬКО то, что поставил предыдущий
# build-deps этого же вызвавшего: build-deps записывает новые пакеты
# (разница 'pacman -Qq' до и после) в свой файл root под /run/rexon-rebuild,
# install-built снимает пересечение переданного списка с записью, и лишь
# пакеты с пометкой «зависимость» ('pacman -Qqd'); запись после установки
# стирается. Нет записи — не снимается ничего: иначе через install-built
# можно было бы снять любой пакет системы, кроме вечного списка.
# ⛔ file — НЕ «любой файл»: только из каталога пересборок вызвавшего
# (~/.cache/rexon/rebuild/<подкаталог>, домашний каталог — из passwd по
# PKEXEC_UID, не из окружения), обычный файл вызвавшего, не ссылка, имя
# файла makepkg (*.pkg.tar[.сжатие]). pacman получает СВОЮ копию в
# каталоге 0700 root, снятую с проверенного файла (cp без разыменования
# ссылок отказывает, если файл подменили во время копии), — подмена
# после проверки ничего не меняет. Так помощник не поставит ни системный
# файл, ни старую версию из кэша pacman, ни чужой файл.
if [ "$op" = build-deps ] || [ "$op" = install-built ]; then
    [ "$family" = arch ] || die rebuild_arch_only "$op"
fi
built=""; built_mode=""
if [ "$op" = install-built ]; then
    [ "$#" -ge 2 ] || die built_args
    built_mode="$1"; built="$2"; shift 2
    case "$built_mode" in
        plain|replace) : ;;
        *) die built_args ;;
    esac
fi

# ── Имя пакета — ИМЯ, а не путь ──────────────────────────────────────
# '/' запрещён везде, кроме атома Gentoo «категория/имя»; ведущий '-' —
# подмена пакета на флаг; ведущая точка и '..' — всегда путь; хвост файла
# пакета ('.deb', '.rpm', …) — файл даже без '/'; '@' законно только как
# группа dnf на Fedora (набор Portage '@world' в 'emerge --unmerge' снёс
# бы систему). Правило то же, что у ядра в is_safe_pkg_arg.
atom_ok() {
    printf '%s' "$1" | grep -Eq '^[A-Za-z0-9][A-Za-z0-9._+:-]*$'
}

pkg_ok() {
    local a="$1" ctg nm
    case "$a" in
        *..*) return 1 ;;
        *.deb|*.rpm|*.apk|*.eopkg|*.xbps|*.tar|*.tgz|*.txz|*.zst|*.xz|*.gz|*.bz2|*.lz4|*.snap|*.flatpakref)
            return 1 ;;
    esac
    [ "$family" != fedora ] || a="${a#@}"
    case "$a" in
        */*)
            [ "$family" = gentoo ] || return 1
            ctg="${a%%/*}"; nm="${a#*/}"
            case "$nm" in */*) return 1 ;; esac
            atom_ok "$ctg" && atom_ok "$nm" ;;
        *) atom_ok "$a" ;;
    esac
}

# Строка зависимости для build-deps: имя (то же правило) и, возможно,
# ограничение версии.
dep_ok() {
    local nm="${1%%[<>=]*}" ver
    ver="${1#"$nm"}"
    pkg_ok "$nm" || return 1
    [ -z "$ver" ] || printf '%s' "$ver" | grep -Eq '^(>=|<=|=|<|>)[A-Za-z0-9][A-Za-z0-9._+:~-]*$'
}

for a in "$@"; do
    case "$a" in
        -*) die arg_dash "$a" ;;
    esac
    if [ "$op" = build-deps ]; then
        dep_ok "$a" || die not_a_name "$a"
    else
        pkg_ok "$a" || die not_a_name "$a"
    fi
done

# ── Удаление: жизненно важное не сносим никогда ──────────────────────
# 'remove' идёт от root и с «не спрашивай»: 'remove linux' оставил бы
# машину без загрузки, 'remove polkit' — без механизма подтверждения. Ни
# одно из этих имён не входит ни в один рабочий стол базы Rexon, поэтому
# честному удалению стола список не мешает.
# ⛔ 28.10.2026: не только точные имена, но и семейства — ядра
# ('linux-cachyos', 'linux-image-…'), драйверы ('nvidia-…', 'mesa'),
# прошивки и микрокод ('*-firmware', '*-ucode'), сборщики initramfs.
# Шаблон — то же правило, что у ядра (is_vital_package); без eval.
is_vital() {
    local k="${1#@}"
    k="${k##*/}"
    case "$k" in
        base|base-files|filesystem|glibc|gcc-libs|bash|coreutils|util-linux|systemd|systemd-libs|systemd-sysvcompat|dbus|dbus-broker|linux|linux-lts|linux-zen|linux-hardened|linux-firmware|kernel|kernel-core|grub|limine|systemd-boot|pacman|apt|dpkg|rpm|dnf|yum|zypper|apk-tools|xbps|eopkg|swupd-client|portage|emerge|polkit|polkit-qt5|sudo|openssl|zlib|rexon|linux-*|kernel-*|gentoo-kernel*|gentoo-sources*|systemd-*|glibc-*|grub-*|sudo-*|opendoas*|polkit-qt*|pacman-*|nvidia*|lib32-nvidia*|mesa*|lib32-mesa*|vulkan-*|lib32-vulkan-*|xf86-video-*|firmware-*|mkinitcpio*|dracut*|booster*|*-firmware|*-ucode|*-dkms) return 0 ;;
    esac
    return 1
}
if [ "$op" = "remove" ]; then
    for a in "$@"; do
        if is_vital "$a"; then
            die vital_pkg "$a"
        fi
    done
fi
# install-built: прежний точный список (сборочные вроде 'linux-headers'
# снимаются законно; их границы — у раздела install-built).
VITAL="base base-files filesystem glibc gcc-libs bash coreutils util-linux systemd systemd-libs systemd-sysvcompat dbus dbus-broker linux linux-lts linux-zen linux-hardened linux-firmware kernel kernel-core grub limine systemd-boot pacman apt dpkg rpm dnf yum zypper apk-tools xbps eopkg swupd-client portage emerge polkit polkit-qt5 sudo openssl zlib rexon"
if [ "$op" = install-built ]; then
    for a in "$@"; do
        for v in $VITAL; do
            if [ "$a" = "$v" ] || [ "${a##*/}" = "$v" ]; then
                die vital_pkg "$a"
            fi
        done
    done
fi

# ── Удаление: стол, в котором сидят, и его экран входа — не снимаются ─
# Окну помощник не верит: что держать, он узнаёт сам, от root.
#   1. Активный экран входа: цель ссылки display-manager.service (нет
#      ссылки — первый включённый юнит из известного списка); держится
#      имя юнита, его пакет по таблице ядра и владелец файла юнита у
#      пакетного менеджера. У LightDM — ещё и приветствия
#      ('lightdm-*greeter*'): lightdm от них не зависит.
#   2. Графические сеансы logind (Type x11/wayland/mir, Class user — любого
#      пользователя, не только вызвавшего): стол — по 'Desktop=' сеанса
#      (XDG_SESSION_DESKTOP) той же таблицей, что у ядра; пакеты стола — из
#      таблицы ядра, группы Arch раскрываются ('pacman -Qqg').
# Ограничения: без systemd/elogind ('loginctl') пункт 2 молчит; сеанс без
# 'Desktop=' (startx, часть входов через greetd) стола не называет —
# держится только экран входа.
dm_unit_now() {
    local link="/etc/systemd/system/display-manager.service" tgt known state
    if [ -L "$link" ]; then
        tgt="$(readlink -f "$link" 2>/dev/null || true)"
        if [ -n "$tgt" ] && [ -e "$tgt" ]; then
            printf '%s\n%s\n' "${tgt##*/}" "$tgt"
            return 0
        fi
    fi
    have systemctl || return 0
    for known in display-manager plasmalogin sddm gdm gdm3 lightdm lxdm greetd ly cosmic-greeter slim nodm xdm entrance emptty tbsm; do
        [ "$known" != display-manager ] || continue
        state="$(systemctl is-enabled "$known.service" 2>/dev/null || true)"
        case "$state" in
            enabled|enabled-runtime|alias|indirect|static)
                tgt="$(systemctl show -p FragmentPath --value "$known.service" 2>/dev/null || true)"
                printf '%s\n%s\n' "$known.service" "$tgt"
                return 0 ;;
        esac
    done
}

owner_of() {
    [ -n "$1" ] && [ -e "$1" ] || return 0
    case "$family" in
        arch) pacman -Qqo -- "$1" 2>/dev/null || true ;;
        debian) dpkg-query -S -- "$1" 2>/dev/null | sed -n 's/^\([^:,]*\)[:,].*/\1/p' | head -n1 || true ;;
        fedora|suse|alt|clear) rpm -qf --qf '%{NAME}\n' -- "$1" 2>/dev/null || true ;;
        alpine) apk info -Wq -- "$1" 2>/dev/null || true ;;
        void) xbps-query -o -- "$1" 2>/dev/null | sed -n 's/^\([^:]*\)-[^-:]*:.*/\1/p' | head -n1 || true ;;
    esac
}

