        esac
    done < <(printf '%s\n' "$d" | tr ':' '\n')
    case "$d" in
        *kde*) printf '%s' kde; return 0 ;;
        *plasma*) printf '%s' kde; return 0 ;;
        *gnome*) printf '%s' gnome; return 0 ;;
        *x-cinnamon*) printf '%s' cinnamon-mint; return 0 ;;
        *cinnamon*) printf '%s' cinnamon-mint; return 0 ;;
        *xfce*) printf '%s' xfce; return 0 ;;
        *mate*) printf '%s' mate; return 0 ;;
        *budgie*) printf '%s' budgie; return 0 ;;
        *pantheon*) printf '%s' pantheon; return 0 ;;
        *dde*) printf '%s' deepin; return 0 ;;
        *deepin*) printf '%s' deepin; return 0 ;;
